/** Stub core: only captured placement data; empty paint bodies are test doubles. */
internal class FixtureFrame(
    override val width: Float,
    override val totalHeight: Float,
    val rows: List<RowPlacement>,
    val styleList: List<StyleDesc> = listOf(StyleDesc(0u.toUShort(), FaceRole.SANS, 16.5f, true)),
) : TranscriptFrame {
    override val revision = 1UL
    var displayCalls = 0
    override fun styles() = styleList
    override fun rowsIn(top: Float, bottom: Float) = rows.filter { it.y + it.height > top && it.y < bottom }
    override fun indexAt(y: Float) = rows.firstOrNull { it.y + it.height > y }?.index ?: rows.lastOrNull()?.index
    override fun placement(index: UInt) = rows.getOrNull(index.toInt())
    override fun indexOf(key: ULong) = rows.firstOrNull { it.key == key }?.index
    override fun display(index: UInt): RowDisplay? {
        val row = placement(index) ?: return null
        displayCalls++
        return RowDisplay(row.key, row.version, width, row.height, "", emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), "", revealAgeMs = null)
    }
}
